  "personas": [
    {"role":"center_admin","person":"varma.asha","story":"Asha Varma looks after the whole organization: its settings, people, roles and connections to other services."},
    {"role":"executive_committee","person":"varma.rohit","story":"Rohit Varma sits on the executive committee: edits people-level information, approves memberships and reads the reports."},
    {"role":"executive_viewer","person":"rathore.kavita","story":"Kavita Rathore is a board member who can look at the dashboards and reports but cannot change anything."},
    {"role":"treasurer","person":"doshiwal.meera","story":"Meera Doshiwal keeps the books: records and refunds gifts, matches the bank, sends statements and closes each month."},
    {"role":"finance_volunteer","person":"doshiwal.kiran","story":"Kiran Doshiwal helps the treasurer by recording gifts received offline and matching bank lines, but cannot refund."},
    {"role":"membership_coordinator","person":"parmar.hemant","story":"Hemant Parmar looks after families and memberships: checks new families, approves applications and keeps their numbers straight."},
    {"role":"religious_coordinator","person":"kataria.bharat","story":"Bharat Kataria plans the religious calendar: bolis, pujans, the practice catalog and the approval of religious content."},
    {"role":"communications_officer","person":"salecha.pooja","story":"Pooja Salecha sends announcements and newsletters, answers the shared inboxes and looks after the message templates."},
    {"role":"content_editor","person":"salecha.nikhil","story":"Nikhil Salecha writes the guide and pages and adds photos; what they write waits for someone to approve it."},
    {"role":"privacy_officer","person":"singhvi.falguni","story":"Falguni Singhvi handles requests to export or delete someone's information and can read the audit log."},
    {"role":"volunteer_coordinator","person":"singhvi.dipak","story":"Dipak Singhvi organizes volunteer groups, shifts, waivers and background checks."},
    {"role":"event_lead","person":"lunawat.sanjay","story":"Sanjay Lunawat runs one event: the attendee list, lunch, volunteers and the checklist for the day.","scope":"ev:tapasvi"},
    {"role":"checkin_volunteer","person":"lunawat.riya","story":"Riya Lunawat scans tickets at the door on the day of an event and sees no giving information.","scope":"ev:tapasvi"},
    {"role":"kitchen_lead","person":"bhandari.vijay","story":"Vijay Bhandari sees the headcounts and the store's prep lists so the kitchen knows how much to make."},
    {"role":"store_lead","person":"nahar.sunil","story":"Sunil Nahar runs the store: the menu, pickup times, orders and stock."},
    {"role":"store_pickup","person":"nahar.rekha","story":"Rekha Nahar hands out store orders at pickup and marks them picked up."},
    {"role":"boli_recorder","person":"kataria.sarla","story":"Sarla Kataria calls the bolis at an event and records the results in person.","scope":"ev:tapasvi"},
    {"role":"pathshala_principal","person":"chopda.deepa","story":"Deepa Chopda runs the Pathshala: terms, classes, levels, teachers and the committee."},
    {"role":"pathshala_committee","person":"chopda.manish","story":"Manish Chopda plans the Pathshala year with its checklists and takes part in its resolutions."},
    {"role":"teacher","person":"bhandari.anita","story":"Anita Bhandari teaches a class: takes attendance, signs off progress and posts class announcements.","scope":"class:j2"},
    {"role":"zone_lead","person":"rathore.lalit","story":"Lalit Rathore looks after one zone: its inbox, the contact details of its families and its reports.","scope":"zone:north"},
    {"role":"community_member","person":"wadhwa.priya","story":"Priya Wadhwa has an account but is not a member yet, and can still RSVP, give, shop and learn."},
    {"role":"membership_reference","person":"parmar.kusum","story":"Kusum Parmar is a member who vouches for newcomers and approves or declines the applications that name them."},
    {"role":"primary_adult","person":"patni.tarun","story":"Tarun Patni is the main adult of a family: manages the household, the children's profiles, payments and RSVPs."},
    {"role":"adult_member","person":"patni.nisha","story":"Nisha Patni is another adult in a family, with their own profile, the family's pledges, RSVPs and payments."},
    {"role":"child","person":"singhvi.zara","story":"Zara Singhvi is a child in the family who can see events and learning but cannot RSVP, pledge or pay."}
  ]
}$demo$::jsonb),
